namespace EthioServe.Application.Abstractions;

/// <summary>Private file storage. Keys are generated by the application, never taken from users.</summary>
public interface IFileStorage
{
    Task SaveAsync(string key, Stream content, CancellationToken ct = default);

    /// <summary>The file's content, or null when no such file exists. The caller disposes the stream.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken ct = default);

    /// <summary>Deleting a file that does not exist is not an error.</summary>
    Task DeleteAsync(string key, CancellationToken ct = default);
}